const assert = require('node:assert');


function test() {
  let candidate = match_parens;
  assert.deepEqual(candidate(["()(", ")"]),"Yes");
  assert.deepEqual(candidate([")", ")"]),"No");
  assert.deepEqual(candidate(["(()(())", "())())"]),"No");
  assert.deepEqual(candidate([")())", "(()()("]),"Yes");
  assert.deepEqual(candidate(["(())))", "(()())(("]),"Yes");
  assert.deepEqual(candidate(["()", "())"]),"No");
  assert.deepEqual(candidate(["(()(", "()))()"]),"Yes");
  assert.deepEqual(candidate(["((((", "((())"]),"No");
  assert.deepEqual(candidate([")(()", "(()("]),"No");
  assert.deepEqual(candidate([")(", ")("]),"No");
  assert.deepEqual(candidate(["(", ")"]),"Yes");
  assert.deepEqual(candidate([")", "("]),"Yes");
}

test();
